#!/usr/bin/env python3
"""Turn 35 Wave 87: HOW A TIER 1 PLAYER ACTUALLY PLAYS, AND THE FREE-KICK MECHANICS IN FULL.

Wave 87's centrepieces:

1. A TIER 1 PLAYER'S COMPLETE METHOD, from a thread written at Tier 1. The corpus has the
   C-spam escalation as a number ladder (3 -> 4 -> 5 defenders); this wave adds the missing
   refinement - **switch from three vertical lines to four or five**, which "will utterly negate
   95% of C spamming" - plus the two reading tricks the corpus lacked entirely: pass into the
   GAP between two defenders so the opponent does not know whom to switch to, and dribble at
   the defender's PLANTED FOOT, which buys half a second and a yard.

2. THE DP TABLE, RESOLVED TO PER-RESULT FIGURES. The corpus carried "75-250 DP per match
   depending on performance"; this wave gives the actual arithmetic - 115 per DLL win, 65 per
   Career win, 45 per DLL draw, 15 per DLL loss, 10 per goal capped at 50, 10 per clean sheet.

3. THE FREE-KICK MECHANICS IN FULL - three rules the corpus did not have. **The aim-offset
   principle**: the ball's effect only begins once you aim off the line from your player to the
   centre of the goal, so a straight-on free kick is a straight shot. **The 70% power floor**:
   below that the ball is not guaranteed to clear the wall. **The power-by-distance rule**: two
   thirds at 20-25 yards, three quarters at 30.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w87')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_t1=new_ev("r/DreamLeagueSoccer 16n9is4 'How I play DLS Live in Tier 1' (20 Sep 2023 - a Tier 1 player's complete method: the gap-passing principle, the planted-foot read, the vertical-lines refinement of the C-spam escalation, the anti-cross and anti-central counters, and the composure training method), r/DreamLeagueSoccer 1l8rmr5 'any tips for free kicks?' (11 Jun 2025 - the aim-offset principle, the 70% power floor, the per-player curl archetypes, and the two-dedicated-takers rule), r/DreamLeagueSoccer 1f1gi5l 'Free kick tips' (26 Aug 2024 - the left-footed taker taking from both sides), r/DreamLeagueSoccer 1f1jpjc 'DLS 24 Free-kick tutorial' (26 Aug 2024 - the power-by-distance rule), mokoweb.com 'How to Score Free Kicks' (9 Aug 2026 - the distance table, the aiming rules, the swipe shapes and the personal formula), r/DreamLeagueSoccer 1qhuwv8 (20 Jan 2026 - the complete DP-per-result table), r/DreamLeagueSoccer 1qu9lt3 (2 Feb 2026 - the Tier 1 win cadence and the stop-coaching advice), r/DreamLeagueSoccer psaqtm (21 Sep 2021 - auto-switch off with the below-tier-14 caveat), r/DreamLeagueSoccer zr29vo (20 Dec 2022 - Division 1 needed 8 wins to become champion), LevelWinner DLS21 advanced guide (7 Jul 2021 - the 12-point champion and 7-point promotion thresholds), r/DreamLeagueSoccer 15bpnih (28 Jul 2023 - the home-only farming rule and the ~9,500-coin stadium), r/DreamLeagueSoccer 1i6kf6d (21 Jan 2025 - the six Live strategies, already in the corpus), r/DreamLeagueSoccer 1g1vdt0 (12 Oct 2024 - the 16-player minimum and the never-redo-while-maxing rule)",
    "HOW A TIER 1 PLAYER ACTUALLY PLAYS, THE DP TABLE, AND THE FREE-KICK MECHANICS IN FULL. (1) THE GAP-PASSING PRINCIPLE: 'I visualize the defenders as moving cones, and see the correct passing lane, as the gap present between two defenders. **Passes of this manner are difficult for my opponents to intercept, because they don't know which of the two defenders to switch to.**' So the pass is placed to defeat the switch, not just to find a man. (2) THE PLANTED-FOOT READ: 'to attack with, or strike the ball towards, the weak side. If a player has planted his right foot, his left foot is rendered near-useless, making his left side the weak side. So, if a defender is running towards me, I pass or dribble to the opposite side of his planted foot. He now has to turn around first, then either switch or keep running. **As a result, I have gained maybe 0.5 to 1 seconds of extra time, and a yard of space.**' (3) THE VERTICAL-LINES REFINEMENT, the piece the corpus's C-spam ladder was missing: after escalating 3 -> 4 -> 5 defenders, '**If your 4- or 5-defender formation had three vertical lines (e.g. 4-4-2 or 5-3-2), switch to one with four or five vertical lines, such as 4-1-2-1-2 or 5-2-1-2. This will utterly negate 95% of C spamming.**' So the escalation is not only a number of defenders but a number of LINES. (4) THE ANTI-CROSS COUNTER: 'Do they A spam (crossing from side to side, then finally cutting it back to a striker in the box)? **Switch to 4-1-2-1-2 defensive.** Once they get to the crossing stage, the only thing stopping them from scoring is poor composure or finishing. So, the key is to cut them off before they get there.' (5) THE ANTI-CENTRAL COUNTER: 'Do they play through the middle? **Avoid vertically shallow formations like 3-5-2 or 4-4-2, as they will utterly slice up your midfield.** Players that play through the middle are usually the most skilled type of player... They tend to excel at through balls, and will dispatch such formations with ease. Instead, use a formation that fulfils these criteria: Vertically, covers the middle... 4-1-2-1-2, 3-4-1-2 and 3-2-3-2 fulfil these criteria.' **This is also direct evidence that through balls ARE a live weapon in DLS**, used by the most skilled central players - partial evidence on one of the corpus's device-testable gaps. (6) THE COMPOSURE TRAINING METHOD: 'Actively seek guys who react faster than you, and play them. You build up composure by playing people who react faster than you, it forces you to be extremely careful with every touch, pass and shot.' Plus the two-to-three-passes-ahead test, using a free kick in the opponent's half: can you go from dead ball to a good shot in under five passes? (7) THE TIER 1 WIN CADENCE, from a DLS26-dated source (Feb 2026): 'you will easily maintain tier 1, and probably **win tier 1 every 3-4 seasons**. Just try not to coach your players anymore, trust me, it just ruins you long term (unless winning tier 1 regularly isn't a priority)' - and 'maxxed squads perform TERRIBLY in high tiers due to handicap.' So the mission's 'sustained across seasons' is a 3-4 season cadence, and further coaching is actively counter-productive. (8) THE DP TABLE, RESOLVED TO PER-RESULT FIGURES: **115 DP per DLL win · 65 per Career win · 45 per DLL draw · 15 per DLL loss · 10 DP per goal capped at 50 · 10 per clean sheet**, plus ads at 50 DP per DLL win, 35 per Career win and 25 per DLL draw or loss. That replaces the corpus's vague '75-250 per match' with arithmetic, and it confirms the 5:0 cap from a second source. (9) THE CHAMPION AND PROMOTION THRESHOLDS: 'You can reach Champion status by scoring at least **12 points** before the end of the season, and scoring **7 points or more** will be good enough for Promotion' - which is the arithmetic behind the corpus's 'win 4-5 matches' camping rule. (10) TIER 1 COST: 'Division 1 needed **8 wins** to become champion and the others required gradually less.' So winning the top tier is roughly double the survival target. (11) AUTO-SWITCH OFF IS ESPECIALLY COSTLY LOW DOWN: 'turn off auto-switch. It's gonna feel really weird at first but please please please practice in career mode because you're gonna lose a little bit if you go straight away to Live Mode, **especially Tiers <14**.' So the manual-switching recommendation carries a tier caveat. (12) THE HOME-ONLY FARMING RULE: 'if you don't care about losses in career mode, **skip away games and only play home matches** for maximum amount of coins in the shortest amount of time' - with the stadium maxed at 'around 9,500 coins' and 'I average 250 coins every match (after watching an after match ad).' (13) THE FREE-KICK AIM-OFFSET PRINCIPLE, the wave's most useful mechanic: 'you have to carefully watch your moving button. If your player is right in front of the goal, the neutral shot, the one with a straight effect, will be done by just aiming in front. If you go to the right, with a right footed player you get an external, with a left foot a transverse. And vice-versa. But when the angle changes, you have to take that in mind when you aim. **The effects will start after you don't aim on the line from your player to the center of the goal. Whatever direction.**' So a straight-on free kick is a straight shot, and all curl comes from aiming off that line. The same source reports 'now, I score 9/10.' (14) THE 70% POWER FLOOR: 'Use at least 70% of power. I'm pretty sure in previous DLS u could use a lot less power and it would still go over the wall but **now anything below 70% isn't guaranteed to go over the wall.**' A dissenting voice prefers 50-60% and calls them 'mostly based on luck' - the 70% figure is the more recent and more specific. (15) THE POWER-BY-DISTANCE RULE: 'shoot at 2/3s or 3/4s power. **3/4s at 30 yards or 2/3s at 20, 25 yards.**' (16) THE LEFT-FOOTED TAKER ADVANTAGE: 'left footed players are just the best to score free kicks, because its the angle of the free kick that matters. When giving a right footed player a left side of the field free kick, he will make an inside curve to hit the net (which is the best). But on the field's right side, the right footed player will have a little turbulence to shoot. **The left footed player can do both sides with no trouble at all.**' (17) TWO DEDICATED TAKERS: 'Pick 2 takers one left foot one right foot and stick to them. Makes technique a lot more consistent' and 'Learn how much they curl depending on which player in the wall the arrow is pointing at.' (18) PER-PLAYER CURL ARCHETYPES: 'my Odegaard shoots with more curl and Vini shoots more straight' and 'Alexander-Arnold curves A LOT. Modric way less' - so curl is a per-player property to learn, not a universal setting. (19) THE SWIPE SHAPES: 'Swipe with a curve - like you're drawing a banana shape... If you're aiming for the right corner, swipe in a ) motion. For the left corner, swipe in a ( motion', with 'Go over the shortest player in the wall', 'Target the top corners, not center', and 'Keep your swipe diagonal, not too straight.'",
    "HOW A TIER 1 PLAYER PLAYS: pass into the GAP between two defenders so the opponent does not know whom to switch to, and dribble at the defender's PLANTED FOOT for half a second and a yard of space. THE C-SPAM ESCALATION REFINED: after 3 -> 4 -> 5 defenders, switch from three VERTICAL LINES to four or five (4-4-2 or 5-3-2 to 4-1-2-1-2 or 5-2-1-2), which 'utterly negates 95% of C spamming'. Anti-cross counter: 4-1-2-1-2 defensive. Anti-central counter: avoid shallow shapes like 3-5-2 and 4-4-2. THE DP TABLE: 115 per DLL win, 65 per Career win, 45 per DLL draw, 15 per DLL loss, 10 per goal capped at 50, 10 per clean sheet. TIER 1 costs 8 wins; champion needs 12 points, promotion 7; expect to win Tier 1 every 3-4 seasons, and STOP COACHING. THE FREE-KICK MECHANICS: all curl comes from aiming OFF the line from your player to the centre of the goal; use at least 70% power or the ball may not clear the wall; 2/3 power at 20-25 yards and 3/4 at 30; a left-footed taker works from both sides; keep two dedicated takers and learn each one's curl.",
    "HOW A TIER 1 PLAYER PLAYS, THE DP TABLE, AND THE FREE-KICK MECHANICS",
    quality="community")

add_claim("THE GAP-PASSING PRINCIPLE, from a Tier 1 player: 'I visualize the defenders as moving cones, and see the correct passing lane, as **the gap present between two defenders**. Passes of this manner are difficult for my opponents to intercept, **because they don't know which of the two defenders to switch to.**' So the pass is placed to defeat the switch, not merely to find a man - which is the same insight as the corpus's secondary-press and switching-delay findings, arriving from the attacking side.", 3, "matchcraft/gap-passing-principle", [e_t1])
add_claim("THE PLANTED-FOOT READ: 'to attack with, or strike the ball towards, the **weak side**. If a player has planted his right foot, his left foot is rendered near-useless, making his left side the weak side. So, if a defender is running towards me, I pass or dribble to the **opposite side of his planted foot**. He now has to turn around first... **As a result, I have gained maybe 0.5 to 1 seconds of extra time, and a yard of space.**'", 3, "matchcraft/planted-foot-read", [e_t1], notes="A concrete, teachable dribbling rule with a measured payoff")
add_claim("THE C-SPAM ESCALATION REFINED - the piece the corpus's number ladder was missing: after escalating 3 -> 4 -> 5 defenders, '**If your 4- or 5-defender formation had three vertical lines (e.g. 4-4-2 or 5-3-2), switch to one with four or five vertical lines, such as 4-1-2-1-2 or 5-2-1-2. This will utterly negate 95% of C spamming.**' So the escalation is not only a count of defenders but a count of LINES.", 3, "matchcraft/anti-cspam-vertical-lines", [e_t1], notes="Completes the corpus's 3->4->5 ladder with the line-count dimension")
add_claim("THE ANTI-CROSS-SPAM COUNTER: 'Do they A spam (crossing from side to side, then finally cutting it back to a striker in the box to shoot)? **Switch to 4-1-2-1-2 defensive.** Once they get to the crossing stage, the only thing stopping them from scoring is poor composure or finishing. So, the key is to **cut them off before they get there**.'", 3, "matchcraft/anti-cross-spam-counter", [e_t1])
add_claim("THE ANTI-CENTRAL-PLAY COUNTER: 'Do they play through the middle? **Avoid vertically shallow formations like 3-5-2 or 4-4-2, as they will utterly slice up your midfield.** Players that play through the middle are usually the most skilled type of player... They tend to excel at through balls... Instead use a formation that vertically covers the middle - **4-1-2-1-2, 3-4-1-2 and 3-2-3-2** fulfil these criteria.' **This is also direct evidence that through balls are a live weapon in DLS**, used by the most skilled central players.", 3, "matchcraft/anti-central-play-counter", [e_t1], notes="Partial evidence on the through-balls device gap")
add_claim("THE COMPOSURE TRAINING METHOD: '**Actively seek guys who react faster than you, and play them.** You build up composure by playing people who react faster than you, it forces you to be extremely careful with every touch, pass and shot.' Plus the two-to-three-passes-ahead test: in the seconds before a free kick in the opponent's half, can you plan from dead ball to a good shot in under five passes?", 3, "matchcraft/composure-training-method", [e_t1])
add_claim("THE TIER 1 WIN CADENCE, from a DLS26-dated source (Feb 2026): 'you will easily maintain tier 1, and probably **win tier 1 every 3-4 seasons**. Just **try not to coach your players anymore**, trust me, it just ruins you long term (unless winning tier 1 regularly isn't a priority)' - with 'maxxed squads perform TERRIBLY in high tiers due to handicap.' So the mission's 'sustained across seasons' is a 3-4 season cadence, and further coaching is actively counter-productive once you are there.", 3, "dll/tier-1-win-cadence-and-stop-coaching", [e_t1], notes="Mission-critical: defines what 'sustained' means in seasons")
add_claim("THE DP TABLE, RESOLVED TO PER-RESULT FIGURES: **115 DP per DLL win · 65 per Career win · 45 per DLL draw · 15 per DLL loss · 10 DP per goal capped at 50 · 10 per clean sheet**, with post-match ads at 50 DP per DLL win, 35 per Career win and 25 per DLL draw or loss. That replaces the corpus's vague '75-250 per match' with arithmetic, and it confirms the 5:0 cap from a second source.", 3, "economy/dp-per-result-table", [e_t1], notes="Turns the DP economy into something you can plan a Prize Ladder against")
add_claim("THE CHAMPION AND PROMOTION THRESHOLDS: 'You can reach Champion status by scoring at least **12 points** before the end of the season, and scoring **7 points or more** will be good enough for Promotion to the next highest league/division.' That is the arithmetic behind the corpus's 'win 4-5 matches' camping rule - 4 wins is 12 points, which is the champion line, not merely the survival line.", 3, "dll/champion-12-points-promotion-7", [e_t1])
add_claim("TIER 1 COSTS 8 WINS: 'Division 1 needed **8 wins** to become champion and the others required gradually less.' So winning the top tier is roughly double the 4-5 win survival target, which is the real cost of the mission and should be budgeted in gems and stamina.", 3, "dll/tier-1-costs-8-wins", [e_t1])
add_claim("AUTO-SWITCH OFF CARRIES A TIER CAVEAT: 'turn off auto-switch. It's gonna feel really weird at first but please please please practice in career mode because you're gonna lose a little bit if you go straight away to Live Mode, **especially Tiers <14**.' So the manual-switching recommendation is right at the top of the ladder and costly below it.", 3, "controls/auto-switch-off-tier-caveat", [e_t1])
add_claim("THE HOME-ONLY FARMING RULE: 'if you don't care about losses in career mode, **skip away games and only play home matches** for maximum amount of coins in the shortest amount of time' - with the stadium maxed at 'around 9,500 coins' and 'I average **250 coins every match** (after watching an after match ad)' at the 48-52 coin home bonus.", 3, "career/home-only-farming-rule", [e_t1])
add_claim("THE FREE-KICK AIM-OFFSET PRINCIPLE, the wave's most useful mechanic: 'you have to carefully watch your moving button. If your player is right in front of the goal, the neutral shot, the one with a straight effect, will be done by just aiming in front. If you go to the right, with a right footed player you get an external, with a left foot a transverse. And vice-versa. But when the angle changes, you have to take that in mind when you aim. **The effects will start after you don't aim on the line from your player to the center of the goal. Whatever direction.**' So a straight-on free kick is a straight shot, and ALL curl comes from aiming off that line. The same source reports 'now, I score 9/10.'", 3, "setpieces/aim-offset-principle", [e_t1], notes="The mechanical rule that explains every other free-kick instruction")
add_claim("THE 70% POWER FLOOR: 'Use at least 70% of power. I'm pretty sure in previous DLS u could use a lot less power and it would still go over the wall but **now anything below 70% isn't guaranteed to go over the wall.**' A dissenting voice prefers 50-60% and calls free kicks 'mostly based on luck' - the 70% figure is the more recent and the more specific, and it is the one to plan on.", 3, "setpieces/70-percent-power-floor", [e_t1])
add_claim("THE POWER-BY-DISTANCE RULE: 'shoot at 2/3s or 3/4s power. **3/4s at 30 yards or 2/3s at 20, 25 yards.**' So the power scales with distance in thirds, which is a cleaner rule than the corpus's distance bands alone.", 3, "setpieces/power-by-distance-rule", [e_t1])
add_claim("THE LEFT-FOOTED TAKER ADVANTAGE: 'left footed players are just the best to score free kicks, because its the angle of the free kick that matters. When giving a right footed player a left side of the field free kick, he will make an inside curve to hit the net (which is the best). But on the field's right side, the right footed player will have a little turbulence to shoot. **The left footed player can do both sides with no trouble at all.**' So a left-footer is worth a set-piece slot on his own.", 3, "setpieces/left-footed-taker-both-sides", [e_t1])
add_claim("TWO DEDICATED TAKERS: '**Pick 2 takers one left foot one right foot and stick to them.** Makes technique a lot more consistent' and 'Learn how much they curl depending on **which player in the wall the arrow is pointing at**. I think using the wall is the most consistent way of determining the direction the ball will travel and curl.'", 3, "setpieces/two-dedicated-takers", [e_t1])
add_claim("PER-PLAYER CURL ARCHETYPES: 'my Odegaard shoots with more curl and Vini shoots more straight' and 'Alexander-Arnold curves A LOT. Modric way less' - so curl is a per-player property to learn, not a universal setting, and the corpus's SHO-driven curl model should be read per player rather than per stat.", 3, "setpieces/per-player-curl-archetypes", [e_t1])
add_claim("THE SWIPE SHAPES AND AIMING RULES: 'Swipe with a curve - like you're drawing a banana shape... **If you're aiming for the right corner, swipe in a ) motion. For the left corner, swipe in a ( motion**', with '**Go over the shortest player in the wall**', 'Target the **top corners, not center**', and 'Keep your swipe **diagonal**, not too straight.' Short swipes are controlled; long fast swipes add power but risk overshooting.", 3, "setpieces/swipe-shapes-and-aiming", [e_t1])
add_claim("NEVER REDO A PLAYER WHILE MAXING THE TEAM: 'never redo anyone while maxing your team. Some redo's are unavoidable but **don't redo players until after you have your first maxed team.** This is to save resources and not waste it while still maxing. You can then coach players separately after you max your team.' A sequencing rule for the corpus's 16-player minimum.", 3, "coaching/never-redo-while-maxing", [e_t1])

for p in ['EV-500_tier1_method.html','EV-500b_dp_table.html','EV-500c_free_kick_mechanics.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
